    // phone notifications
    'Phone notifications' => ['د موبایل خبرتیاوې', 'اطلاعیه‌های موبایلی'],
    'Get SmartClass alerts on this phone or computer even when the site is closed. E-mail and the bell keep working as they are.' => ['د SmartClass خبرتیاوې پدې موبایل یا کمپیوټر کې ترلاسه کړئ، حتی کله چې سایټ تړلی وي. ای‌میل او زنګوله لکه پخوا کار کوي.', 'اطلاعیه‌های SmartClass را روی این موبایل یا کمپیوتر دریافت کنید، حتی وقتی سایت بسته است. ای‌میل و زنگوله مثل قبل کار می‌کنند.'],
    'Phone notifications are switched off for this school.' => ['د دې ښوونځي لپاره د موبایل خبرتیاوې بندې دي.', 'اطلاعیه‌های موبایلی برای این مکتب خاموش است.'],
    'Turn them on below.' => ['لاندې یې چالان کړئ.', 'در پایین آن را روشن کنید.'],
    'Checking…' => ['کتل کېږي…', 'در حال بررسی…'],
    'Turn on for this device' => ['پدې وسیله کې چالان کړئ', 'روی این دستگاه روشن کنید'],
    'Turn off for this device' => ['پدې وسیله کې بند کړئ', 'روی این دستگاه خاموش کنید'],
    'Send me a test' => ['یو ازموینیز پیغام راولېږئ', 'یک پیام آزمایشی برایم بفرستید'],
    'Phone notifications are on for this device.' => ['د موبایل خبرتیاوې پدې وسیله کې چالان دي.', 'اطلاعیه‌های موبایلی روی این دستگاه روشن است.'],
    'Phone notifications are off on this device.' => ['د موبایل خبرتیاوې پدې وسیله کې بندې دي.', 'اطلاعیه‌های موبایلی روی این دستگاه خاموش است.'],
    "Notifications are blocked in this browser. Allow them in the browser's site settings, then come back." => ['خبرتیاوې په دې براوزر کې بندې دي. د براوزر په سایټ تنظیماتو کې یې اجازه ورکړئ، بیا بېرته راشئ.', 'اطلاعیه‌ها در این مرورگر مسدود است. در تنظیمات سایت مرورگر اجازه دهید و دوباره برگردید.'],
    'This browser cannot show phone notifications. On an iPhone, add SmartClass to the Home Screen first.' => ['دا براوزر نشي کولی د موبایل خبرتیاوې وښيي. په آیفون کې لومړی SmartClass کور سکرین ته زیات کړئ.', 'این مرورگر نمی‌تواند اطلاعیه‌های موبایلی را نشان دهد. در آیفون ابتدا SmartClass را به صفحهٔ اصلی اضافه کنید.'],
    'Something went wrong. Please try again.' => ['یو څه ستونزه رامنځته شوه. مهرباني وکړئ بیا هڅه وکړئ.', 'مشکلی پیش آمد. لطفاً دوباره تلاش کنید.'],
    'The alert text shows on your lock screen, so turn this on only on a device you keep to yourself.' => ['د خبرتیا متن ستاسو د لاک سکرین په مخ کې ښکاري، نو دا یوازې په هغه وسیله کې چالان کړئ چې یوازې تاسو یې کاروئ.', 'متن اطلاعیه روی صفحهٔ قفل شما دیده می‌شود، پس آن را فقط روی دستگاهی روشن کنید که خودتان استفاده می‌کنید.'],
    'Allow phone notifications for everyone' => ['د ټولو لپاره د موبایل خبرتیاوو ته اجازه ورکړئ', 'اجازهٔ اطلاعیه‌های موبایلی برای همه'],
    'Turn off to stop all phone notifications at once. A staging copy never sends them.' => ['د ټولو موبایل خبرتیاوو په یو ځل درولو لپاره یې بند کړئ. ازمایښتي کاپي هیڅکله نه لیږي.', 'برای توقف همهٔ اطلاعیه‌های موبایلی یک‌جا آن را خاموش کنید. نسخهٔ آزمایشی هرگز نمی‌فرستد.'],
    'Sent. It should appear on your phone in a moment.' => ['ولېږل شو. باید یو شېبه وروسته ستاسو په موبایل کې ښکاره شي.', 'فرستاده شد. باید لحظه‌ای دیگر روی موبایل شما نمایان شود.'],
